-- Table: masterdata_employee
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_employee (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    employee_number VARCHAR(30)  NOT NULL UNIQUE,
    user_id         BIGINT UNIQUE REFERENCES masterdata_user(id),
    name            VARCHAR(150) NOT NULL,
    position        VARCHAR(100) NOT NULL,
    department_id   BIGINT REFERENCES masterdata_department(id),
    cost_center_id  BIGINT REFERENCES masterdata_cost_center(id),
    email           VARCHAR(255),
    phone           VARCHAR(50),
    address         TEXT,
    hire_date       DATE,
    status          VARCHAR(20)  NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'inactive', 'resigned')),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);
